Notes on the loading standard:
- Profile values are expressions, but profile text must never be executed, so values are
  parsed with a restricted AST walk (literals, containers, and arithmetic such as
  ``8 * 1024``) instead of ``eval``.
- The ``plugin`` key selects a *built-in* transform plugin by name, resolved from the
  ``plugins.BUILTIN_PLUGINS`` registry as the README contract specifies, instead of
  importing an arbitrary module. New plugins are added to ``plugins.py``; the loader
  itself never needs to change.
"""

from __future__ import annotations

import ast
import operator

from plugins import BUILTIN_PLUGINS

# Arithmetic / bitwise operators allowed inside profile values.
_ALLOWED_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.LShift: operator.lshift,
    ast.RShift: operator.rshift,
    ast.BitOr: operator.or_,
    ast.BitAnd: operator.and_,
    ast.BitXor: operator.xor,
}

# Unary operators allowed inside profile values.
_ALLOWED_UNARYOPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Invert: operator.invert,
}


def _parse_value(raw: str):
    """Parse a profile value expression into a Python object.

    Accepts the expression forms profiles rely on (literals, lists, dicts, sets, and
    computed sizes like ``8 * 1024``) while refusing anything that could run code (names,
    attribute access, calls, comprehensions, ...).
    """
    try:
        tree = ast.parse(raw, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"invalid profile value {raw!r}: {exc.msg}") from None
    return _eval_node(tree.body, raw)


def _eval_node(node: ast.AST, raw: str):
    """Recursively evaluate a whitelisted expression node.

    Raises ``ValueError`` for any node outside the allowed subset, so no profile text is
    ever executed.
    """
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.List):
        return [_eval_node(elt, raw) for elt in node.elts]
    if isinstance(node, ast.Tuple):
        return tuple(_eval_node(elt, raw) for elt in node.elts)
    if isinstance(node, ast.Set):
        return {_eval_node(elt, raw) for elt in node.elts}
    if isinstance(node, ast.Dict):
        if any(key is None for key in node.keys) or any(val is None for val in node.values):
            raise ValueError(f"unsupported profile value {raw!r}: dict unpacking is not allowed")
        return {_eval_node(key, raw): _eval_node(val, raw) for key, val in zip(node.keys, node.values)}
    if isinstance(node, ast.BinOp) and type(node.op) in _ALLOWED_BINOPS:
        left = _eval_node(node.left, raw)
        right = _eval_node(node.right, raw)
        return _ALLOWED_BINOPS[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in _ALLOWED_UNARYOPS:
        return _ALLOWED_UNARYOPS[type(node.op)](_eval_node(node.operand, raw))
    raise ValueError(f"unsupported profile value {raw!r}: only literals and arithmetic are allowed")


def _load_plugin(value: object):
    """Resolve the reserved ``plugin`` key to a built-in transform plugin instance.

    Only names present in ``plugins.BUILTIN_PLUGINS`` are accepted, per the README
    contract; the profile text can never cause an arbitrary module to be imported.
    """
    if not isinstance(value, str):
        raise ValueError(f"plugin must be named by a string, got {type(value).__name__}")
    try:
        transform_cls = BUILTIN_PLUGINS[value]
    except KeyError:
        known = ", ".join(sorted(BUILTIN_PLUGINS))
        raise ValueError(f"unknown plugin {value!r}; built-in plugins: {known}") from None
    return transform_cls()


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    Returns ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``:
    every non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a built-in transform plugin by name (an
    instance, or ``None`` when the profile sets no plugin).
    """
    settings: dict = {}
    plugin = None
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, raw = line.partition("=")
        key, raw = key.strip(), raw.strip()
        if not sep or not key or not raw:
            raise ValueError(f"invalid profile line {line!r}: expected 'key = value'")
        value = _parse_value(raw)
        if key == "plugin":
            plugin = _load_plugin(value)
        else:
            settings[key] = value
    return {"settings": settings, "plugin": plugin}
